const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign
} = require("docx");

const NAVY = "1F2A44";
const GOLD = "B08D57";
const LIGHT = "F2EEE8";
const GREY = "555555";

const cellBorder = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333" })]
  });
}

function sectionLabel(text) {
  return new Paragraph({
    spacing: { before: 160, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: NAVY })]
  });
}

function bodyPara(text, opts = {}) {
  return new Paragraph({
    spacing: { before: opts.before || 60, after: opts.after || 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333", italics: !!opts.italics })]
  });
}

function caseTitle(num, title) {
  return [
    new Paragraph({
      spacing: { before: 360, after: 40 },
      children: [new TextRun({ text: `Case Study #${num}`, font: "Arial", size: 20, bold: true, color: GOLD, allCaps: true })]
    }),
    new Paragraph({
      spacing: { after: 60 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 4 } },
      children: [new TextRun({ text: title, font: "Arial", size: 30, bold: true, color: NAVY })]
    })
  ];
}

function practiceType(text) {
  return new Paragraph({
    spacing: { before: 100, after: 120 },
    children: [
      new TextRun({ text: "Practice Type: ", font: "Arial", size: 22, bold: true, color: NAVY }),
      new TextRun({ text, font: "Arial", size: 22, color: GREY })
    ]
  });
}

function clientLine(text) {
  return new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [new TextRun({ text: `Client: ${text}`, font: "Arial", size: 22, bold: true, italics: true, color: NAVY })]
  });
}

function headCell(text, w) {
  return new TableCell({
    borders, width: { size: w, type: WidthType.DXA },
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 20, bold: true, color: "FFFFFF" })] })]
  });
}

function rowCell(text, w, opts = {}) {
  return new TableCell({
    borders, width: { size: w, type: WidthType.DXA },
    shading: { fill: opts.fill || "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 20, bold: !!opts.bold, color: opts.color || "333333" })] })]
  });
}

function resultsTable(rows) {
  const W = 9360, c0 = 3360, c1 = 3000, c2 = 3000;
  const headerRow = new TableRow({
    tableHeader: true,
    children: [headCell("Metric", c0), headCell("Before", c1), headCell("After", c2)]
  });
  const bodyRows = rows.map((r, i) => {
    const fill = i % 2 === 0 ? LIGHT : "FFFFFF";
    return new TableRow({
      children: [
        rowCell(r[0], c0, { fill, bold: true, color: NAVY }),
        rowCell(r[1], c1, { fill }),
        rowCell(r[2], c2, { fill, bold: true, color: "2E7D32" })
      ]
    });
  });
  return new Table({ width: { size: W, type: WidthType.DXA }, columnWidths: [c0, c1, c2], rows: [headerRow, ...bodyRows] });
}

function leakTable(rows) {
  const W = 9360, c0 = 6360, c1 = 3000;
  const headerRow = new TableRow({
    tableHeader: true,
    children: [headCell("Revenue Leak", c0), headCell("Estimated Annual Impact", c1)]
  });
  const bodyRows = rows.map((r, i) => {
    const fill = i % 2 === 0 ? LIGHT : "FFFFFF";
    return new TableRow({
      children: [
        rowCell(r[0], c0, { fill, color: NAVY }),
        rowCell(r[1], c1, { fill, bold: true, color: "2E7D32" })
      ]
    });
  });
  return new Table({ width: { size: W, type: WidthType.DXA }, columnWidths: [c0, c1], rows: [headerRow, ...bodyRows] });
}

const children = [];

// Cover header
children.push(new Paragraph({
  spacing: { after: 40 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 26, bold: true, color: NAVY, allCaps: true })]
}));
children.push(new Paragraph({
  spacing: { after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 6 } },
  children: [new TextRun({ text: "Client Results & Case Studies", font: "Arial", size: 36, bold: true, color: NAVY })]
}));
children.push(new Paragraph({
  spacing: { before: 120, after: 60 },
  children: [new TextRun({ text: "Premium Practice Edition: Established Med Spas at $2.5M and Above", font: "Arial", size: 24, bold: true, italics: true, color: GOLD })]
}));
children.push(bodyPara("The following results come from established practices already generating strong revenue. At this level, the constraint is rarely demand. It is the systems that convert, retain, and compound the revenue already moving through the practice. These are the kinds of gains that show up when a practice doing $2.5 million installs a full Growth Engine.", { before: 80, after: 80 }));

// ---------- Case Study #6 ----------
children.push(...caseTitle(6, "Added $624,000 in Annual Revenue Through Memberships and Package Architecture"));
children.push(practiceType("Multi-Provider Medical Spa, $2.5M annual revenue"));
children.push(sectionLabel("Challenge"));
children.push(bodyPara("Revenue was strong but flat. The practice had grown on walk-ins, referrals, and repeat injectables, and had hit a ceiling. The deeper issues were structural:"));
[
  "Almost no recurring revenue, nearly every dollar was transactional",
  "No membership program to lock in repeat visits",
  "Treatments sold one at a time rather than in packages",
  "Frequent discounting to close, which quietly eroded margin",
  "No lifetime value strategy, so high-value patients were not being grown"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("What We Implemented"));
[
  "A tiered membership program priced for predictable monthly recurring revenue",
  "Package and bundle architecture across the top revenue services",
  "Lifetime value frameworks to grow each patient relationship over time",
  "Staff sales training so the team could present memberships and packages with confidence",
  "A discounting policy that protected margin without losing the sale"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("Results After 120 Days"));
children.push(resultsTable([
  ["Monthly Revenue", "$208,000", "$260,000"],
  ["Active Members", "0", "175+"],
  ["Recurring Monthly Revenue", "$0", "$32,000+"],
  ["Average Transaction Value", "Single Service", "Bundled Packages"],
  ["Discounting", "Frequent", "Controlled"]
]));
children.push(sectionLabel("Financial Impact"));
children.push(bodyPara("The membership and package systems added roughly $52,000 per month in new revenue, with a meaningful portion now recurring and predictable. That is an additional $624,000 per year, built on patients the practice already had."));
children.push(clientLine("Rebecca M., Multi-Provider Med Spa"));

// ---------- Case Study #7 ----------
children.push(...caseTitle(7, "Recovered $340,000 in Annual Revenue Leaks at a High-Volume Practice"));
children.push(practiceType("High-Volume Aesthetics Practice, $2.5M annual revenue"));
children.push(sectionLabel("Challenge"));
children.push(bodyPara("The owner assumed the next phase of growth meant more marketing spend. A full Revenue Leak Audit and patient journey review told a different story. The practice was busy, and the money was leaking on the way out the door:"));
[
  "Rebooking happening inconsistently at checkout",
  "Follow-up on unbooked consultations left to memory and good intentions",
  "Front desk converting fewer inbound inquiries than the volume justified",
  "Upsell and add-on conversations skipped during high-traffic days",
  "Lapsed patients with no reactivation system reaching out to them"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("What We Found"));
children.push(leakTable([
  ["Missed Rebooking at Checkout", "$95,000+"],
  ["Inconsistent Consultation Follow-Up", "$80,000+"],
  ["Front Desk Conversion Losses", "$70,000+"],
  ["Skipped Upsell and Add-On Revenue", "$55,000+"],
  ["Lapsed Patient Retention Gaps", "$40,000+"]
]));
children.push(new Paragraph({
  spacing: { before: 140, after: 60 },
  children: [
    new TextRun({ text: "Total Identified Opportunity: ", font: "Arial", size: 24, bold: true, color: NAVY }),
    new TextRun({ text: "$340,000+ annually", font: "Arial", size: 24, bold: true, color: "2E7D32" })
  ]
}));
children.push(sectionLabel("What We Implemented"));
[
  "Mandatory rebooking built into the checkout script and workflow",
  "Automated, AI-assisted follow-up for every unbooked consultation",
  "Front desk conversion training with simple tracked benchmarks",
  "Structured upsell prompts the team could use without feeling pushy",
  "A standing reactivation campaign for lapsed patients"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("Result"));
children.push(bodyPara("Within the first 90 days the practice had captured the majority of the identified opportunity, without a dollar of additional advertising. The systems now run quietly in the background and keep the revenue from escaping in the first place."));
children.push(clientLine("Jonathan R., High-Volume Aesthetics Practice"));

// ---------- Case Study #8 ----------
children.push(...caseTitle(8, "Scaled From $2.5M Toward $3.4M With a Full Growth Engine Installation"));
children.push(practiceType("Established Medical Spa, two locations"));
children.push(sectionLabel("Challenge"));
children.push(bodyPara("This was a healthy, well-run practice that had plateaued. The owner wanted real growth without burning out the team or buying their way there with paid traffic. The pieces existed, but nothing was connected into a system:"));
[
  "Lead follow-up depended on whoever had a free moment",
  "Consultation conversion sat in the low forties",
  "No-shows were a persistent drain on the calendar",
  "Reputation and reviews were strong but not actively managed",
  "No partnership pipeline feeding consistent new patients"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("What We Implemented"));
children.push(bodyPara("A full Growth Engine installation over a twelve-month partnership, layered in stages:"));
[
  "CRM buildout with full pipeline visibility across both locations",
  "AI follow-up sequences so no lead or consultation went cold",
  "Staff sales training tied to real call patterns from the practice",
  "Membership and package architecture for recurring revenue",
  "A reputation engine to generate and route reviews consistently",
  "Strategic partnerships feeding qualified referrals, plus optional new revenue streams such as longevity and wellness offerings"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("Results Over 12 Months"));
children.push(resultsTable([
  ["Annualized Revenue", "$2.5M", "$3.4M"],
  ["Consultation Conversion", "41%", "64%"],
  ["No-Show Rate", "22%", "9%"],
  ["Recurring Revenue", "Minimal", "Established Base"],
  ["Lead Follow-Up", "Manual", "Automated"]
]));
children.push(sectionLabel("Financial Impact"));
children.push(bodyPara("The practice added roughly $900,000 in annualized revenue, a 36% increase, without adding locations or relying on heavier ad spend. The infrastructure now supports continued growth toward seven figures per location."));
children.push(clientLine("Stephanie K., Two-Location Medical Spa"));

// ---------- Case Study #9 ----------
children.push(...caseTitle(9, "Improved Profit Margins at a $2.5M Practice Without Adding Headcount"));
children.push(practiceType("Aesthetic Practice & Wellness Clinic, $2.5M annual revenue"));
children.push(sectionLabel("Challenge"));
children.push(bodyPara("Top-line revenue looked great. The owner's take-home did not match it. The practice was working hard for revenue that was leaking out through margin before it ever reached the bottom line:"));
[
  "Heavy discounting used as the default closing tool",
  "Pricing that had not kept pace with cost or demand",
  "Service mix weighted toward lower-margin treatments",
  "High-value patients treated the same as one-time buyers",
  "No clear view of which services actually drove profit"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("What We Implemented"));
[
  "A margin audit ranking every core service by true profitability",
  "Strategic price increases on high-demand, high-value treatments",
  "A shift in service mix toward higher-margin offerings and memberships",
  "Package architecture that raised average ticket without discounting",
  "Lifetime value frameworks to prioritize and grow the best patients"
].forEach(t => children.push(bullet(t)));
children.push(sectionLabel("Results"));
children.push(resultsTable([
  ["Net Profit Margin", "18%", "27%"],
  ["Default Discounting", "Routine", "Rare"],
  ["Service Mix", "Low-Margin Heavy", "Profit-Weighted"],
  ["Average Ticket", "Flat", "Higher"],
  ["Headcount Added", "—", "None"]
]));
children.push(sectionLabel("Financial Impact"));
children.push(bodyPara("On the same revenue base, the margin improvement moved more than $200,000 additional dollars to the bottom line per year. No new staff, no new locations, and no increase in marketing spend. The practice simply kept more of what it was already earning."));
children.push(clientLine("Catherine D., Aesthetic Practice & Wellness Clinic"));

// ---------- Aggregate ----------
children.push(new Paragraph({
  spacing: { before: 380, after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 4 } },
  children: [new TextRun({ text: "Aggregate Impact at the Premium Tier", font: "Arial", size: 30, bold: true, color: NAVY })]
}));
children.push(bodyPara("Across established practices at $2.5 million and above, the patterns hold steady:", { before: 120 }));
[
  "Annualized revenue gains of $300,000 to $900,000 from existing patient flow",
  "Recurring revenue programs built from a standing start",
  "Consultation conversion improvements of 20 to 25 percentage points",
  "Profit margin gains without adding staff or locations",
  "Six-figure revenue leaks identified and closed within the first 90 days"
].forEach(t => children.push(bullet(t)));

children.push(new Paragraph({
  spacing: { before: 240, after: 60 },
  children: [new TextRun({ text: "The Bottom Line", font: "Arial", size: 26, bold: true, color: NAVY })]
}));
children.push(bodyPara("At this level, more leads is rarely the answer. The growth is already inside the practice. Our job is to find where it is escaping, install the systems that keep it, and build the recurring revenue that compounds year after year."));

const doc = new Document({
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { run: { color: GOLD }, paragraph: { indent: { left: 540, hanging: 280 } } } }] }
    ]
  },
  styles: { default: { document: { run: { font: "Arial", size: 22 } } } },
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 } } },
    children
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Luxora_Case_Studies_Premium_Tier.docx", buffer);
  console.log("written");
});

