const NAVY = "1F2A44";
const GOLD = "B08D57";
const LIGHT = "F2EEE8";
const GREY = "555555";
const GREEN = "2E7D32";

const cellBorder = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 }, spacing: { after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333" })]
  });
}
function sectionLabel(text) {
  return new Paragraph({
    spacing: { before: 160, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: NAVY })]
  });
}
function bodyPara(text, opts = {}) {
  return new Paragraph({
    spacing: { before: opts.before || 60, after: opts.after || 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333", italics: !!opts.italics })]
  });
}
function caseTitle(num, title) {
  return [
    new Paragraph({
      spacing: { before: 360, after: 40 },
      children: [new TextRun({ text: `Case Study #${num}`, font: "Arial", size: 20, bold: true, color: GOLD, allCaps: true })]
    }),
    new Paragraph({
      spacing: { after: 60 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 4 } },
      children: [new TextRun({ text: title, font: "Arial", size: 30, bold: true, color: NAVY })]
    })
  ];
}
function tierHeader(text, sub) {
  const arr = [new Paragraph({
    spacing: { before: 420, after: sub ? 40 : 80 },
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 2 } },
    children: [new TextRun({ text: "  " + text, font: "Arial", size: 28, bold: true, color: "FFFFFF" })]
  })];
  if (sub) arr.push(bodyPara(sub, { before: 80, after: 80 }));
  return arr;
}
function practiceType(text) {
  return new Paragraph({
    spacing: { before: 100, after: 120 },
    children: [
      new TextRun({ text: "Practice Type: ", font: "Arial", size: 22, bold: true, color: NAVY }),
      new TextRun({ text, font: "Arial", size: 22, color: GREY })
    ]
  });
}
function clientLine(text) {
  return new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [new TextRun({ text: `Client: ${text}`, font: "Arial", size: 22, bold: true, italics: true, color: NAVY })]
  });
}
function totalLine(label, value) {
  return new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [
      new TextRun({ text: label + ": ", font: "Arial", size: 24, bold: true, color: NAVY }),
      new TextRun({ text: value, font: "Arial", size: 24, bold: true, color: GREEN })
    ]
  });
}
function headCell(text, w) {
  return new TableCell({
    borders, width: { size: w, type: WidthType.DXA }, shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 140, right: 140 }, verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 20, bold: true, color: "FFFFFF" })] })]
  });
}
function rowCell(text, w, opts = {}) {
  return new TableCell({
    borders, width: { size: w, type: WidthType.DXA }, shading: { fill: opts.fill || "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 140, right: 140 }, verticalAlign: VerticalAlign.CENTER,
