const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType, VerticalAlign
} = require("docx");

const NAVY = "1F2A44";
const GOLD = "B08D57";
const LIGHT = "F2EEE8";
const GREEN = "2E7D32";
const cellBorder = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };

function bodyPara(text, opts = {}) {
  return new Paragraph({ spacing: { before: opts.before || 60, after: opts.after || 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333", italics: !!opts.italics, bold: !!opts.bold })] });
}
function bullet(text) {
  return new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333" })] });
}
function sectionHead(text) {
  return new Paragraph({ spacing: { before: 320, after: 100 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 4 } },
    children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: NAVY })] });
}
function hCell(text, w) {
  return new TableCell({ borders, width: { size: w, type: WidthType.DXA }, shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 130, right: 130 }, verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 20, bold: true, color: "FFFFFF" })] })] });
}
function cell(runs, w, fill) {
  const paras = Array.isArray(runs[0]) ? runs.map(r => new Paragraph({ spacing: { after: 20 }, children: r })) : [new Paragraph({ children: runs })];
  return new TableCell({ borders, width: { size: w, type: WidthType.DXA }, shading: { fill: fill || "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 130, right: 130 }, verticalAlign: VerticalAlign.TOP, children: paras });
}
function tr(children) { return new TableRow({ children }); }
function t(text, o = {}) { return new TextRun({ text, font: "Arial", size: 20, color: o.color || "333333", bold: !!o.bold, italics: !!o.italics }); }

const children = [];

// Header
children.push(new Paragraph({ spacing: { after: 40 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 24, bold: true, color: NAVY, allCaps: true })] }));
children.push(new Paragraph({ spacing: { after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 6 } },
  children: [new TextRun({ text: "Case Study Selection Guide", font: "Arial", size: 34, bold: true, color: NAVY })] }));
children.push(new Paragraph({ spacing: { before: 100, after: 60 },
  children: [new TextRun({ text: "Internal Use: For Bethany and Aanchal", font: "Arial", size: 22, bold: true, italics: true, color: GOLD })] }));
children.push(bodyPara("Match the prospect to the right two or three studies and send only those. Never send the full library. The studies feel custom when each one speaks directly to the pain the prospect just named, and the prospect never sees the full scope of the system in a single piece.", { before: 80, after: 100 }));

// How to use
children.push(sectionHead("How to Use This"));
bullets1 = [
  "Find the row that matches what the prospect actually said, in their words.",
  "Send the studies listed, in the order listed. Lead with the first. The second and third are supporting proof.",
  "Two studies is the target. Three is the ceiling. More than three weakens the effect.",
  "For established prospects at $2M and above, default to the Premium Tier studies (#1 to #6). For growth-stage prospects, the Foundational studies (#7 to #11) feel more relatable."
];
bullets1.forEach(b => children.push(bullet(b)));

// Mapping table
children.push(sectionHead("Match the Pain to the Study"));
const C0 = 3300, C1 = 2700, C2 = 3360;
const header = tr([hCell("If they say something like...", C0), hCell("Send, in this order", C1), hCell("Why it lands", C2)]);

const rows = [
  [`"My marketing isn't working" or "I just need more leads"`,
    [["#2", true], ["Revenue Leaks"], ["#10", true], ["Secret Shopper"]],
    "Reframes the problem from a lead problem to a leak problem. Shows the money is escaping, not missing."],
  [`"We've plateaued" or "Revenue is flat"`,
    [["#3", true], ["Full Growth Engine"], ["#1", true], ["Memberships"]],
    "Shows the path from stalled to scaling, plus a brand-new recurring revenue stream they do not have yet."],
  [`"I work this hard and barely keep any of it"`,
    [["#4", true], ["Margins"], ["#1", true], ["Memberships"]],
    "Proves take-home can grow without growing the top line. Speaks to profit, not just revenue."],
  [`"Everything is transactional" or "No recurring revenue"`,
    [["#1", true], ["Memberships"], ["#4", true], ["Margins"]],
    "Memberships and a smarter service mix turn one-time buyers into predictable monthly revenue."],
  [`"My front desk is a mess" or "We keep losing front desk staff"`,
    [["#5", true], ["Front Desk"], ["#10", true], ["Secret Shopper"]],
    "Names the exact chaos they live with and shows the booking revenue recovered once it is fixed."],
  [`"I'm worried my top injector will leave" (often unspoken)`,
    [["#6", true], ["Head Injector"], ["#1", true], ["Memberships"]],
    "The key-person fear most premium owners feel and rarely say out loud. Shows the practice is protected."],
  [`"I'm doing everything myself" or "I'm the bottleneck"`,
    [["#11", true], ["Capacity"], ["#9", true], ["Infrastructure"]],
    "Capacity and systems without adding headcount. Speaks directly to the owner who cannot let go."],
  [`"We have no real systems" or "I'm flying blind"`,
    [["#9", true], ["Infrastructure"], ["#8", true], ["Qualified Consults"]],
    "From zero infrastructure to full visibility, tracking, and follow-up that runs without them."],
  [`"Leads come in but they die" or "Our follow-up is slow"`,
    [["#8", true], ["Qualified Consults"], ["#7", true], ["48.6% in 30 Days"]],
    "Response time, automated follow-up, and a concrete conversion lift. The fix for a leaky pipeline."],
  [`"Just show me it actually works"`,
    [["#7", true], ["48.6% in 30 Days"], ["#2", true], ["Revenue Leaks"]],
    "Fast, concrete proof. A 30-day result and a 90-day recovery for the skeptic who wants evidence first."]
];

const tableRows = [header];
rows.forEach((r, i) => {
  const fill = i % 2 === 0 ? LIGHT : "FFFFFF";
  const sendPairs = [];
  for (let j = 0; j < r[1].length; j += 2) {
    sendPairs.push([t(r[1][j][0] + " ", { bold: true, color: NAVY }), t(r[1][j + 1][0], { color: "333333" })]);
  }
  tableRows.push(tr([
    cell([t(r[0], { italics: true, color: NAVY })], C0, fill),
    cell(sendPairs, C1, fill),
    cell([t(r[2])], C2, fill)
  ]));
});
children.push(new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [C0, C1, C2], rows: tableRows }));

// Study index
children.push(sectionHead("Quick Study Index"));
children.push(bodyPara("Premium Tier: established practices at $2.5M and above.", { bold: true, before: 100, after: 40 }));
const idxPremium = [
  ["#1", "Memberships and Package Architecture", "+$624,000/year in recurring and packaged revenue"],
  ["#2", "Revenue Leaks Recovered", "$340,000+ in leaks found, majority recovered in 90 days"],
  ["#3", "Full Growth Engine", "$2.5M to $3.4M in 12 months, conversion 41% to 64%"],
  ["#4", "Margins Without Headcount", "Net margin 18% to 27%, $200,000+ to the bottom line"],
  ["#5", "Front Desk Stabilized", "$180,000 in lost bookings recovered, owner off the desk"],
  ["#6", "Head Injector Risk Solved", "Roughly 80% of patients retained through her departure"]
];
const idxFound = [
  ["#7", "Revenue Growth 48.6% in 30 Days", "$37K to $55K/month, conversion 34% to 62%"],
  ["#8", "15+ Qualified Consults Per Month", "Response time to under 5 minutes, $108,000+/year"],
  ["#9", "Complete Growth Infrastructure", "CRM, automation, retention built from zero"],
  ["#10", "Secret Shopper Review", "$110,000+ in revenue opportunities uncovered"],
  ["#11", "Capacity Without Adding Staff", "$100,000 to $250,000+ in headroom, no new hires"]
];
function indexLine(num, name, head) {
  return new Paragraph({ spacing: { after: 50 }, children: [
    t(num + "  ", { bold: true, color: GOLD }),
    t(name + ". ", { bold: true, color: NAVY }),
    t(head, { color: "333333" })
  ]});
}
idxPremium.forEach(r => children.push(indexLine(r[0], r[1], r[2])));
children.push(bodyPara("Foundational: growth-stage practices, more relatable for smaller owners.", { bold: true, before: 140, after: 40 }));
idxFound.forEach(r => children.push(indexLine(r[0], r[1], r[2])));

// Rules of thumb
children.push(sectionHead("Three Rules That Make This Work"));
[
  "Send two, three at most. The power is in relevance, not volume.",
  "Lead with the study that matches their exact words. The rest is backup.",
  "Pull from the library, never hand over the whole thing. Each prospect should feel like you chose these for them, because you did."
].forEach(b => children.push(bullet(b)));

children.push(new Paragraph({ spacing: { before: 220, after: 40 },
  children: [new TextRun({ text: "Before any external send: ", font: "Arial", size: 20, bold: true, color: NAVY }),
    new TextRun({ text: "confirm every figure against real client data, or present it as a projection. Do not send a specific dollar result as a client outcome unless it can be substantiated.", font: "Arial", size: 20, italics: true, color: "666666" })] }));

const doc = new Document({
  numbering: { config: [{ reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { run: { color: GOLD }, paragraph: { indent: { left: 540, hanging: 280 } } } }] }] },
  styles: { default: { document: { run: { font: "Arial", size: 22 } } } },
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 } } }, children }]
});
Packer.toBuffer(doc).then(b => { fs.writeFileSync("/home/claude/Luxora_Case_Study_Selection_Guide.docx", b); console.log("written"); });

